\label{lem:small-weight}
		For $b\in C_c^\infty(U)$ with $\operatorname{supp} b\subset\operatorname{supp} w$,
		\begin{equation}\label{eq:small-weight}
			\left|\int_Ub u_1u_2u_3\,d V_g\right|
			\le C\|b\|_{L^4(U)}+C_b\lambda^{-1/2},
		\end{equation}
		where $C$ is independent of the derivatives of $b$.

\label{lem:kernel-phase}
	Suppose $K_g=\varepsilon F$, $0<\varepsilon\le\varepsilon_0$,
	$|F|\ge c>0$, and $\|F\|_{C^N}\le C_N$ on this neighborhood.
	For $\lambda\ge1$ and smooth $a_\lambda(x,s)$ of fixed compact support
	and uniform smooth bounds, there are a real phase $\Phi$ and smooth
	$b_\lambda$ such that
	\begin{equation}\label{eq:stationary-kernel}
		\lambda^{3/2}\int e^{i\lambda(\phi_1+\phi_2+\phi_3)}
		a_\lambda(x,s)\,d V_g(x)
		=\lambda^{1/2}e^{i\lambda\Phi(s)}b_\lambda(s)+O(\lambda^{-1/2}),
	\end{equation}
	where $\|b_\lambda\|_{C^N}\le C_N$ and $\Phi$ satisfies
	Lemma~\ref{lem:trilinear}. All bounds are uniform in $t_1,t_2,t_3$.

\label{lem:nonzero-operator}
	Suppose $K_g=\varepsilon F$ on a fixed neighborhood of $\operatorname{supp} w$, where
	$0<\varepsilon\le1$, $|F|\ge c>0$, and $\|F\|_{C^N}\le C_N$.
	For \eqref{eq:distance-operator} and weights of fixed compact support and
	uniform smooth bounds,
	\begin{equation}\label{eq:nonzero-operator}
		\left|\int w\prod_{j=1}^3 E_{\lambda,j}f_j\,d V_g\right|
		\le C(1+\lambda\varepsilon)^{-1/6}\prod_{j=1}^3\|f_j\|_2.
	\end{equation}

\label{lem:finite-order}
		Let $k\ge0$ be an integer. On a fixed neighborhood of $\operatorname{supp} w$, suppose
		\begin{equation}\label{eq:uniform-class}
			K_g=\varepsilon F,\qquad 0<\varepsilon\le1,\qquad
			\|F\|_{C^N}\le C_N,\qquad
			\max_{|\alpha|\le k}|\partial^\alpha F(x)|\ge c>0.
		\end{equation}
		For \eqref{eq:distance-operator} and weights with uniform smooth bounds,
		\begin{equation}\label{eq:all-operators}
			\left|\int w\prod_{j=1}^3 E_{\lambda,j}f_j\,d V_g\right|
			\le C(1+\lambda\varepsilon)^{-1/[2(k+3)]}\prod_{j=1}^3\|f_j\|_2.
		\end{equation}

\label{lem:bessel}
		For $0<t_0<t_1\le\mu/4$,
		\begin{equation}\label{eq:global-mass}
			\int_{t_0}^{t_1}W_\lambda(t)^2\frac{\,d t}{t}
			\ge c\mu^{-1}\log(t_1/t_0)-C\mu^{-2}.
		\end{equation}
		For $t\ge t_0\ge2\mu$,
		\begin{equation}\label{eq:global-decay}
			0<W_\lambda(t)\le e^{-(t-t_0)/2}W_\lambda(t_0).
		\end{equation}

\label{lem:cusp-fourier}
		For any $y_0>0$, let $u\in L^2(Y)$ solve $-\Delta_g u=\lambda^2u$ on
		$Y=(\mathbb R/\mathbb Z)\times(y_0,\infty)$ with the hyperbolic metric above.
		There are constants $c_n\in\mathbb C$, $n\ne0$, such that
		\begin{equation}\label{eq:global-fourier}
			\begin{split}
				u(x,y)&=\sqrt y\sum_{n\ne0}c_nW_\lambda(2\pi|n|y)e^{2\pi inx},\\
				\|u\|_{L^2(Y)}^2
				&=\sum_{n\ne0}|c_n|^2
				\int_{y_0}^\infty W_\lambda(2\pi|n|y)^2\frac{\,d y}{y}.
			\end{split}
		\end{equation}
		For an integer $N\ge1$, let $u_{\ge N}$ be the sum in
		\eqref{eq:global-fourier} restricted to $|n|\ge N$.
		If $H\ge4\max\{y_0,1\}$ and $NH\ge4\mu$, then
		\begin{equation}\label{eq:global-high-bound}
			|u_{\ge N}(x,y)|\le Ce^{-cNy}\|u\|_{L^2(Y)},\qquad y\ge H.
		\end{equation}

\label{lem:bessel-triple}
		For $a,b>0$, $\mu\ge1$, and $\omega\in C^2((0,\infty))$,
		\begin{equation}\label{eq:global-triple-bound}
			\begin{aligned}
				&\left|\int_0^\infty\omega(y)y^{-1/2}
				W_\lambda(ay)W_\lambda(by)W_\lambda((a+b)y)\,d y\right|\\
				&\qquad\le C\mu^{-3/2}(a+b)^{-1/2}
				\sum_{j=0}^2\|(y\partial_y)^j\omega\|_\infty,
			\end{aligned}
		\end{equation}
		provided the sum on the right is finite. The constant is independent of
		$a/b$.

\label{prop:sharp-slow}
		There are fixed $U\Subset\mathbb R^2$ and nonzero $0\le w\in C_c^\infty(U)$
		with the following property. For every
		$\varepsilon_*:[1,\infty)\to(0,\infty)$ with $\varepsilon_*(\lambda)\to0$,
		there are a fixed complete smooth metric $g$ on $\mathbb R^2$ and real solutions
		\begin{equation}\label{eq:sharp-normalization}
			-\Delta_ge_\lambda=\lambda^2e_\lambda\quad\text{on }U,
			\qquad \|e_\lambda\|_{L^2(U)}=1,
		\end{equation}
		such that, for some $\lambda_n\to\infty$,
		\begin{equation}\label{eq:sharp-ratio}
			\int_Uw e_\lambda^3\,d V_g\longrightarrow0,\qquad
			\frac{\displaystyle\int_Uw e_{\lambda_n}^3\,d V_g}
			{\varepsilon_*(\lambda_n)}\longrightarrow+\infty.
		\end{equation}
		Moreover,
		\[
		w(x,0)=0,\qquad K_g(x,y)<0\quad(y\ne0),\qquad
		\nabla^jK_g(x,0)=0\quad(j\ge0).
		\]

\label{prop:sharp-finite}
		\textup{(i)} For the fixed rectangle $U$ in \eqref{eq:fixed-U-w}, there
		is a fixed $0\le w\in C_c^\infty(U)$ with $w(0)>0$ such that, for every
		integer $m\ge0$, a fixed complete smooth metric $g_m$ satisfies
		\begin{equation}\label{eq:sharp-finite-condition}
			\inf_{x\in\operatorname{supp} w}\sum_{j=0}^m|\nabla^jK_{g_m}(x)|_{g_m}>0
		\end{equation}
		and admits real local solutions with
		\begin{equation}\label{eq:power-sharpness}
			\begin{gathered}
				-\Delta_{g_m}e_\lambda=\lambda^2e_\lambda\quad\text{on }U,\qquad
				\|e_\lambda\|_{L^2(U,g_m)}=1,\\
				c_m\lambda^{-1/(6+2m)}\le\int_Uw e_\lambda^3\,d V_{g_m}
				\le C_m\lambda^{-1/(6+2m)}
			\end{gathered}
		\end{equation}
		for all sufficiently large $\lambda$.

		\textup{(ii)} On the standard round sphere $S^2$, for every
		sufficiently large even $n$, there is a real spherical harmonic $e_n$ with
		\begin{equation}\label{eq:sphere-sharpness}
			\begin{gathered}
				-\Delta_{S^2}e_n=\lambda_n^2e_n,\qquad
				\lambda_n=\sqrt{n(n+1)},\qquad\|e_n\|_{L^2(S^2)}=1,\\
				c\lambda_n^{-1/6}\le\int_{S^2}e_n^3\,d V_g
				\le C\lambda_n^{-1/6}.
			\end{gathered}
		\end{equation}
